import{_ as e,H as n,f as s,i as p}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"25 | 业务逻辑漏洞：好的开始是成功的一半","description":"","frontmatter":{},"headers":[{"level":2,"title":"业务逻辑漏洞的定义","slug":"业务逻辑漏洞的定义","link":"#业务逻辑漏洞的定义","children":[]},{"level":2,"title":"业务逻辑漏洞的原因","slug":"业务逻辑漏洞的原因","link":"#业务逻辑漏洞的原因","children":[]},{"level":2,"title":"业务逻辑漏洞的影响","slug":"业务逻辑漏洞的影响","link":"#业务逻辑漏洞的影响","children":[]},{"level":2,"title":"业务逻辑漏洞实例","slug":"业务逻辑漏洞实例","link":"#业务逻辑漏洞实例","children":[]},{"level":2,"title":"业务逻辑漏洞的抵御","slug":"业务逻辑漏洞的抵御","link":"#业务逻辑漏洞的抵御","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"Web漏洞挖掘实战/25｜业务逻辑漏洞：好的开始是成功的一半.md","filePath":"Web漏洞挖掘实战/25｜业务逻辑漏洞：好的开始是成功的一半.md","lastUpdated":1795536081000}'),t={name:"Web漏洞挖掘实战/25｜业务逻辑漏洞：好的开始是成功的一半.md"};function i(l,a,c,o,r,h){return n(),s("div",null,[...a[0]||(a[0]=[p(`<h1 id="_25-业务逻辑漏洞-好的开始是成功的一半" tabindex="-1">25 | 业务逻辑漏洞：好的开始是成功的一半 <a class="header-anchor" href="#_25-业务逻辑漏洞-好的开始是成功的一半" aria-label="Permalink to &quot;25 | 业务逻辑漏洞：好的开始是成功的一半&quot;">​</a></h1><p>你好，我是王昊天。</p><p>在前几年，杭州发生了一件让人脑洞大开的违法犯罪行为，竟然有一名男子在超市购物时，将昂贵商品的标签替换为便宜商品的标签，从而实现了将 6000 余元的商品仅仅花了 48 元就买回了家。</p><p>这名男子得手的原因就是超市的业务逻辑存在漏洞，允许男子修改商品上的标签，给超市造成了很大的损失。事实上，在 Web 应用中也是有逻辑漏洞存在的，这些漏洞也会给 Web 应用带来巨大的损失。</p><p>所以今天，我会给你讲解 Web 应用中的业务逻辑漏洞。首先我们会介绍什么是业务逻辑漏洞，让你先对这一漏洞有一定的理解。然后我们会学习业务逻辑漏洞存在的原因，进而分析出业务逻辑漏洞可能会导致的后果及影响。最后，我们会一起了解现实中发生的业务逻辑漏洞事例，加深你对业务逻辑漏洞的理解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/25/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/25/1.png" alt=""></a></p><p>下面，让我们先从最基础的定义开始吧。</p><h2 id="业务逻辑漏洞的定义" tabindex="-1">业务逻辑漏洞的定义 <a class="header-anchor" href="#业务逻辑漏洞的定义" aria-label="Permalink to &quot;业务逻辑漏洞的定义&quot;">​</a></h2><p>当开发者在设计一个 Web 应用时，没有进行充分的考虑，导致 Web 应用的逻辑设计不够充分，就容易导致业务逻辑漏洞的产生。这么说有点抽象，我们一起来看一个示例帮助你理解它。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/25/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/25/2.png" alt=""></a></p><p>这是一个购物网站，我们打开了一个其中的衣服，它的价格十分昂贵，需要 1337 美元。我们可以输入想要购买的数量，然后点击 Add to cart 按钮，将它添加到购物车。为了尝试攻击这个应用，我们在点击添加购物车时，用 BurpSuite 拦截到报文如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /cart HTTP/1.1</span></span>
<span class="line"><span>Host: acf51f0c1eaff6e6c0f28fae00f80084.web-security-academy.net</span></span>
<span class="line"><span>Cookie: session=R4pFnL8mM0tsrGHnit3y3ZdPgYQd9n1B</span></span>
<span class="line"><span>Content-Length: 50</span></span>
<span class="line"><span>Cache-Control: max-age=0</span></span>
<span class="line"><span>Sec-Ch-Ua: &quot;Chromium&quot;;v=&quot;95&quot;, &quot;;Not A Brand&quot;;v=&quot;99&quot;</span></span>
<span class="line"><span>Sec-Ch-Ua-Mobile: ?0</span></span>
<span class="line"><span>Sec-Ch-Ua-Platform: &quot;macOS&quot;</span></span>
<span class="line"><span>Upgrade-Insecure-Requests: 1</span></span>
<span class="line"><span>Origin: https://acf51f0c1eaff6e6c0f28fae00f80084.web-security-academy.net</span></span>
<span class="line"><span>Content-Type: application/x-www-form-urlencoded</span></span>
<span class="line"><span>User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML,</span></span>
<span class="line"><span>Accept: text/html,application/xhtml+xml,application/xml;q=0.9,image/avif,image/we</span></span>
<span class="line"><span>Sec-Fetch-Site: same-origin</span></span>
<span class="line"><span>Sec-Fetch-Mode: navigate</span></span>
<span class="line"><span>Sec-Fetch-User: ?1</span></span>
<span class="line"><span>Sec-Fetch-Dest: document</span></span>
<span class="line"><span>Referer: https://acf51f0c1eaff6e6c0f28fae00f80084.web-security-academy.net/produc</span></span>
<span class="line"><span>Accept-Encoding: gzip, deflate</span></span>
<span class="line"><span>Accept-Language: zh-CN,zh;q=0.9</span></span>
<span class="line"><span>Connection: close</span></span>
<span class="line"><span>productId=1&amp;redir=PRODUCT&amp;quantity=10&amp;price=133700</span></span></code></pre></div><p>看到这个报文，我眼前一亮，可以发现我们不仅仅可以输入数量，甚至还可以输入产品的价格。那我们就自然的会去尝试对它进行修改，这里我们将它改为 1，由于价格的单位是按分计算的，所以从购物车中我们看到，产品的价格变为了 1 美分。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/25/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/Web%E6%BC%8F%E6%B4%9E%E6%8C%96%E6%8E%98%E5%AE%9E%E6%88%98/images/25/3.png" alt=""></a></p><p>这样，我们就可以花费很便宜的价格，去购买很昂贵的商品了。这就是一个业务逻辑漏洞，它的根本原因在于允许用户修改单价。虽然 Web 应用的前端页面没有修改单价的选项，但是攻击者可以通过一些软件例如 BurpSuite 去修改单价，进而导致漏洞的发生。</p><p>这就是应用开发者考虑不够充分导致的问题，他们可能认为只要前端页面无法修改单价就行，但是攻击者会有别的方式去修改。究其业务逻辑漏洞的根本原因，就是开发者会对用户的行为做一些合法的预期设想，然后根据这个预期来进行安全设计和响应，一旦攻击者进行一些开发者意想不到的操作，就很容易导致一些问题的发生。</p><p>总体来说，业务逻辑漏洞是非常多样化的，它与本身应用的功能和类型相关，因此想要鉴别它是非常困难的，因为这需要一定的业务知识。所以我们很难用漏洞探测工具去对业务逻辑漏洞进行检测，这也导致了业务逻辑漏洞成为一些漏洞测试员的主要工作内容。</p><p>在了解完业务逻辑漏洞的原因后，下面让我们深入研究一下这个漏洞是如何引起的。</p><h2 id="业务逻辑漏洞的原因" tabindex="-1">业务逻辑漏洞的原因 <a class="header-anchor" href="#业务逻辑漏洞的原因" aria-label="Permalink to &quot;业务逻辑漏洞的原因&quot;">​</a></h2><p>业务逻辑漏洞发生的原因就是 Web 应用的设计者和开发者对用户的行为做出了错误的假设。这个假设使得 Web 应用对于用户的输入验证不够充分。</p><p>比如，应用开发者认为用户只会通过访问浏览器进行数据的上传，那么很可能就会把输入验证放到前端去处理。但是攻击者可以通过拦截代理软件例如 BurpSuite，很容易就能绕过 Web应用对于输入的检测，从而给 Web 应用带来威胁。</p><p>对于用户输入验证的不充分，最终导致攻击者可以对应用做出一些预期之外的操作。由于应用开发者没有想到这种情况，所以应用无法安全地处理这些操作，这就导致了漏洞的发生。因此，在业务逻辑复杂的 Web 应用中，很容易会出现业务逻辑漏洞。</p><p>到这里，你已经明白了业务逻辑漏洞是什么，以及它是如何产生的，我们已经有了足够的基础知识储备，这样我们可以更好地学习业务逻辑漏洞的影响了。</p><h2 id="业务逻辑漏洞的影响" tabindex="-1">业务逻辑漏洞的影响 <a class="header-anchor" href="#业务逻辑漏洞的影响" aria-label="Permalink to &quot;业务逻辑漏洞的影响&quot;">​</a></h2><p>由于不同 Web 应用具有不同的业务逻辑，所以业务逻辑漏洞的影响范围很广很杂。但是很多的逻辑漏洞攻击，都可能会对整个 Web 应用造成很严重的后果。</p><p>从根本上来讲，业务逻辑漏洞产生的影响与它的功能有关。</p><p>比如登录授权机制上的逻辑漏洞就会对应用产生数据泄漏的影响，攻击者可以利用它进行权限提升或者绕过登录验证，从而获得一些敏感数据。</p><p>而经济交易中的逻辑漏洞，则可能会允许攻击者窃取资金或进行欺诈行为，导致很多的经济损失。</p><p>我们需要知道，有的业务逻辑漏洞可能无法让攻击者直接受益，但是会对应用的业务造成一些负面影响，例如影响正常用户的使用。</p><p>了解完业务逻辑漏洞的影响后，我们来看两个现实中的业务逻辑漏洞案例。</p><h2 id="业务逻辑漏洞实例" tabindex="-1">业务逻辑漏洞实例 <a class="header-anchor" href="#业务逻辑漏洞实例" aria-label="Permalink to &quot;业务逻辑漏洞实例&quot;">​</a></h2><p>这两个案例都很典型，希望你以后遇到类似的应用时，可以联想到它可能存在业务逻辑漏洞。</p><p>首先，我们回顾下之前学习的那个购物网站，我们利用 BurpSuite 修改了产品的价格，导致可以用 1 美分购买原本价格昂贵的大衣。这是网购中典型的业务逻辑漏洞，它仅仅在客户端做了些输入限制，我们很容易就可以绕过它。这个逻辑漏洞是由于对客户端验证的过度信任造成的。</p><p>应用如果没有做好对异常输入的处理，也会造成逻辑漏洞。下面，让我们再看一个简单的示例。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$transferAmount = $_POST[&#39;amount&#39;];</span></span>
<span class="line"><span>$currentBalance = $user-&gt;getBalance();</span></span>
<span class="line"><span>if ($transferAmount &lt;= $currentBalance) {</span></span>
<span class="line"><span>  // Complete the transfer</span></span>
<span class="line"><span>} else {</span></span>
<span class="line"><span>  // Block the transfer: insufficient funds</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>这是一个银行转账应用，用户可以通过 POST 方式上传转账的金额。我们不难看出它判断了转账金额是否超出余额，如果余额支持转账，那么就进行交易操作，否则拒绝交易。这是一个正确的逻辑，但是如果攻击者将 amount 设置为负值，那么攻击者就会收到它的绝对值的金额。这就是一个业务逻辑漏洞，它产生的原因就是应用没有对异常输入做正确处理。</p><p>看完这些可怕的逻辑漏洞实例，我们不难知道，做好业务逻辑漏洞的抵御措施是非常重要的。所以我们也不妨学习下如何抵御业务逻辑漏洞吧！</p><h2 id="业务逻辑漏洞的抵御" tabindex="-1">业务逻辑漏洞的抵御 <a class="header-anchor" href="#业务逻辑漏洞的抵御" aria-label="Permalink to &quot;业务逻辑漏洞的抵御&quot;">​</a></h2><p>简单来说，抵御业务逻辑漏洞有两个关键。第一点，确保应用的开发者和测试者理解应用的功能。第二点，避免开发者对用户的行为以及应用其他部分的行为做出错误的预期。</p><p>展开来说，我们需要明确自己对应用输入作出的预期假设，并执行必要的逻辑验证去判断输入是否符合预期，在将所有的输入经过验证之后才予以使用。</p><p>同时，确保所有的开发者和测试者完全理解，开发时做出的假设输入以及应用在不同的情形下进行的响应，这可以帮助应用开发团队尽早发现逻辑漏洞。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当我们发现一个逻辑漏洞时，我们可以分析Web应用中存在的逻辑缺陷，帮助我们发现应用其</span></span></code></pre></div><p>他的弱点，然后将发现的弱点统统解决掉，这可以让我们的业务逻辑更加安全。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在今天的学习中，我们完整地学习了业务逻辑漏洞。</p><p>首先，我们学习了什么是业务逻辑漏洞，在学习过程中，我们看了一个卖衣服的示例，了解到业务逻辑漏洞就是，应用的开发者在设计一个 Web 应用时，没有进行充分的考虑，导致 Web应用的逻辑设计不够充分，从而引起的安全问题。</p><p>然后，我们进一步分析了业务逻辑漏洞的产生原因，它主要是由于应用的设计者对于用户的行为作出了错误的预期，并且对用户的输入限制做得不到位，使得应用在处理预期之外的输入时，做出错误的处理，这就导致了业务逻辑漏洞。</p><p>接下来，我们分析了业务逻辑漏洞的影响，了解到由于业务逻辑的不同，业务逻辑漏洞造成的影响也不同，这与它的功能相关，例如授权机制的逻辑漏洞会造成数据泄漏的影响。</p><p>最后，我们了解了现实中的业务逻辑漏洞示例，分析它们的引起方式有过度信任客户端验证以及错误处理非预期输入。它们造成的后果都是非常严重的，所以我们还学习了抵御这一漏洞的方法，知道了防范业务逻辑漏洞需要做到两个关键，即确保应用的开发者和测试者理解应用的功能，并且避免开发者对用户的行为以及应用其他部分的行为做出错误的预想。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>你能想出一个其他的业务逻辑漏洞示例吗？</p><p>欢迎在评论区留下你的思考。如果觉得今天的内容对你有所帮助的话，也欢迎你把课程分享给其他同事或朋友，我们共同学习进步！</p>`,52)])])}const b=e(t,[["render",i]]);export{d as __pageData,b as default};
